tryit.args:
{
  "sql": "select plan, count(*) from accounts group by 1"
}

featured.selection:
searchDeals(query: $query, first: $first) {
  edges {
    node { id name stage amount closeDate owner { id name } }
  }
  pageInfo { hasNextPage endCursor }
}

tryit.upstream:
POST https://crm-sandbox.a-intel.com/graphql
query ($query: String!, $first: Int) { searchDeals(query: $query, first: $first) { edges { node { id name stage amount } } } }
variables: {"query": "renewal Q4", "first": 2}
